/**
 * playback-auth — OAuth token-exchange relay for the "Playback for Notion" iOS app.
 *
 * The Notion client secret must never ship inside a mobile app, so the app
 * sends the short-lived authorization code here and this Worker performs the
 * code -> token exchange against Notion. Codes and tokens are never stored
 * and never written to logs; only route/status metadata is logged.
 */
import { privacyHTML, supportHTML } from "./pages";

// `Env` is generated by `wrangler types` from wrangler.jsonc vars.
// The secret is not part of the config, so it is added explicitly here.
type WorkerEnv = Env & {
  NOTION_CLIENT_SECRET: string;
};

const NOTION_TOKEN_URL = "https://api.notion.com/v1/oauth/token";
const SERVICE = "playback-auth";
const VERSION = "1.0.0";
const MAX_BODY_CHARS = 8192;

function logEvent(event: string, fields: Record<string, string | number>): void {
  console.log(JSON.stringify({ event, service: SERVICE, ...fields }));
}

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
    },
  });
}

function htmlResponse(html: string): Response {
  return new Response(html, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "public, max-age=3600",
    },
  });
}

function methodNotAllowed(allow: string): Response {
  return new Response(JSON.stringify({ error: "method_not_allowed" }), {
    status: 405,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      allow,
    },
  });
}

type JsonObject = Record<string, unknown>;

async function readJsonObject(
  request: Request,
): Promise<{ ok: true; value: JsonObject } | { ok: false; response: Response }> {
  const contentType = request.headers.get("content-type") ?? "";
  if (!contentType.toLowerCase().includes("application/json")) {
    return { ok: false, response: jsonResponse({ error: "unsupported_media_type" }, 415) };
  }
  // Bodies for this API are tiny (a code or a refresh token). Reading the
  // text is safe because anything larger than MAX_BODY_CHARS is rejected.
  const text = await request.text();
  if (text.length > MAX_BODY_CHARS) {
    return { ok: false, response: jsonResponse({ error: "payload_too_large" }, 413) };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { ok: false, response: jsonResponse({ error: "invalid_json" }, 400) };
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return { ok: false, response: jsonResponse({ error: "invalid_json" }, 400) };
  }
  return { ok: true, value: parsed as JsonObject };
}

function stringField(obj: JsonObject, key: string, maxLength: number): string | null {
  const value = obj[key];
  if (typeof value !== "string" || value.length === 0 || value.length > maxLength) {
    return null;
  }
  return value;
}

async function callNotionTokenEndpoint(
  env: WorkerEnv,
  payload: JsonObject,
  event: string,
): Promise<Response> {
  const clientId = env.NOTION_CLIENT_ID;
  const clientSecret = env.NOTION_CLIENT_SECRET;
  if (!clientId || !clientSecret) {
    logEvent(event, { status: 500, reason: "not_configured" });
    return jsonResponse({ error: "server_not_configured" }, 500);
  }
  let upstream: Response;
  try {
    upstream = await fetch(NOTION_TOKEN_URL, {
      method: "POST",
      headers: {
        authorization: `Basic ${btoa(`${clientId}:${clientSecret}`)}`,
        accept: "application/json",
        "content-type": "application/json",
      },
      body: JSON.stringify(payload),
    });
  } catch {
    logEvent(event, { status: 502, reason: "upstream_unreachable" });
    return jsonResponse({ error: "upstream_unavailable" }, 502);
  }
  logEvent(event, { status: upstream.status });
  // Stream Notion's JSON straight back (tokens on success, error detail on
  // failure) without buffering or inspecting it.
  return new Response(upstream.body, {
    status: upstream.status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
    },
  });
}

async function handleExchange(request: Request, env: WorkerEnv): Promise<Response> {
  const parsed = await readJsonObject(request);
  if (!parsed.ok) return parsed.response;

  const code = stringField(parsed.value, "code", 1024);
  if (code === null) {
    return jsonResponse({ error: "missing_code" }, 400);
  }
  const configuredRedirect = env.NOTION_REDIRECT_URI;
  if (!configuredRedirect) {
    logEvent("oauth_exchange", { status: 500, reason: "redirect_not_configured" });
    return jsonResponse({ error: "server_not_configured" }, 500);
  }
  const givenRedirect = parsed.value["redirect_uri"];
  if (givenRedirect !== undefined && givenRedirect !== configuredRedirect) {
    return jsonResponse({ error: "redirect_uri_mismatch" }, 400);
  }
  return callNotionTokenEndpoint(
    env,
    { grant_type: "authorization_code", code, redirect_uri: configuredRedirect },
    "oauth_exchange",
  );
}

async function handleRefresh(request: Request, env: WorkerEnv): Promise<Response> {
  const parsed = await readJsonObject(request);
  if (!parsed.ok) return parsed.response;

  const refreshToken = stringField(parsed.value, "refresh_token", 2048);
  if (refreshToken === null) {
    return jsonResponse({ error: "missing_refresh_token" }, 400);
  }
  return callNotionTokenEndpoint(
    env,
    { grant_type: "refresh_token", refresh_token: refreshToken },
    "oauth_refresh",
  );
}

function handleCallback(url: URL, env: WorkerEnv): Response {
  const schemePattern = /^[a-z][a-z0-9+.-]*$/i;
  const scheme = schemePattern.test(env.APP_SCHEME) ? env.APP_SCHEME : "playbacknotion";

  const params = new URLSearchParams();
  for (const key of ["code", "state", "error", "error_description"]) {
    const value = url.searchParams.get(key);
    if (value !== null) params.set(key, value);
  }
  if (!params.has("code") && !params.has("error")) {
    params.set("error", "missing_code");
  }
  const location = `${scheme}://oauth?${params.toString()}`;
  logEvent("oauth_callback", { status: 302, hasCode: params.has("code") ? 1 : 0 });
  return new Response(null, { status: 302, headers: { location } });
}

async function route(request: Request, env: WorkerEnv): Promise<Response> {
  const url = new URL(request.url);
  const path = url.pathname.length > 1 ? url.pathname.replace(/\/+$/, "") : url.pathname;
  const method = request.method.toUpperCase();

  switch (path) {
    case "/health":
      if (method !== "GET" && method !== "HEAD") return methodNotAllowed("GET, HEAD");
      return jsonResponse({ ok: true, service: SERVICE, version: VERSION });
    case "/oauth/callback":
      if (method !== "GET") return methodNotAllowed("GET");
      return handleCallback(url, env);
    case "/oauth/exchange":
      if (method !== "POST") return methodNotAllowed("POST");
      return handleExchange(request, env);
    case "/oauth/refresh":
      if (method !== "POST") return methodNotAllowed("POST");
      return handleRefresh(request, env);
    case "/privacy":
      if (method !== "GET" && method !== "HEAD") return methodNotAllowed("GET, HEAD");
      return htmlResponse(privacyHTML);
    case "/support":
      if (method !== "GET" && method !== "HEAD") return methodNotAllowed("GET, HEAD");
      return htmlResponse(supportHTML);
    default:
      return jsonResponse({ error: "not_found" }, 404);
  }
}

export default {
  async fetch(request: Request, env: WorkerEnv): Promise<Response> {
    try {
      return await route(request, env);
    } catch {
      logEvent("unhandled_error", { status: 500 });
      return jsonResponse({ error: "internal_error" }, 500);
    }
  },
} satisfies ExportedHandler<WorkerEnv>;
